// Strips the quoted reply chain and signature so the assistant sees the
// customer's actual message rather than the last five emails appended to it.
//
// IMAP 'resolved' format gives textPlain / textHtml / subject / from.
// HTML is only used when there is no plain-text part, which is rare but does
// happen with mail sent from some webmail clients.

function htmlToText(html) {
  return html
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>');
}

const out = [];

for (const item of $input.all()) {
  const mail = item.json;

  let body = mail.textPlain || '';
  if (!body && mail.textHtml) body = htmlToText(mail.textHtml);

  // Everything from the first quote marker onward belongs to the previous
  // thread, not to what the customer just wrote.
  const cutPoints = [
    /^On .+ wrote:$/m,
    /^-{2,}\s*Original Message\s*-{2,}/im,
    /^_{5,}$/m,
    /^From: .+$/m,
    /^Sent from my /m,
    /^Get Outlook for /m,
  ];
  for (const marker of cutPoints) {
    const match = body.match(marker);
    if (match && match.index !== undefined) body = body.slice(0, match.index);
  }

  body = body.replace(/\r/g, '').replace(/\n{3,}/g, '\n\n').trim();

  // `from` arrives either as a string or as a parsed address object
  // depending on the sending client, so both shapes are handled.
  let from = '';
  if (typeof mail.from === 'string') from = mail.from;
  else if (mail.from?.text) from = mail.from.text;
  else if (mail.from?.value?.[0]?.address) from = mail.from.value[0].address;

  out.push({
    json: {
      from,
      subject: mail.subject || '',
      body,
      messageId: mail.messageId || '',
    },
  });
}

return out;
